<style>
:root{--dn-navy:#465474;--dn-navy-deep:#2f3b58;--dn-champagne:#e7cc98;--dn-cream:#f7f4ee;--dn-ink:#36425f;--dn-white:#fff;--dn-muted:#748098;--dn-shadow:0 24px 70px rgba(41,50,74,.13);--dn-display:'Chakra Petch','Arial Narrow',sans-serif;--dn-body:'Manrope','Segoe UI',sans-serif}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:var(--dn-ink);background:#fff;font-family:var(--dn-body);line-height:1.65}.dn302-page{overflow:hidden}img{display:block;max-width:100%}a{color:inherit;text-decoration:none}button,input,textarea{font:inherit}.dn-container{width:min(1680px,calc(100% - 64px));margin-inline:auto}.dn-display,h1,h2,h3{font-family:var(--dn-display);font-weight:600;line-height:1.13}.dn-section{position:relative;padding:110px 0}.dn-eyebrow{margin:0 0 18px;color:var(--dn-champagne);font-family:var(--dn-display);font-weight:600;letter-spacing:.22em;text-transform:uppercase}.dn-title{margin:0;font-size:clamp(40px,4vw,45px);color:var(--dn-ink)}.dn-heading{margin-bottom:56px}.dn-heading.center{text-align:center}.dn-heading p:last-child{max-width:900px;margin:20px auto 0;color:var(--dn-muted);font-size:17px}.dn-btn{display:inline-flex;align-items:center;justify-content:center;gap:16px;min-height:72px;padding:0 42px;border:0;background:var(--dn-champagne);color:var(--dn-ink);font-family:var(--dn-display);font-weight:600;text-transform:uppercase;letter-spacing:.03em;cursor:pointer;transition:.25s ease}.dn-btn:hover{background:#f1dbae;transform:translateY(-3px)}

/* DN Square: custom display treatment built from a Vietnamese-complete geometric face. */
.dn-title,.dn-hero h1,.dn-card h3,.dn-stat strong{font-feature-settings:'ss01' 1,'kern' 1;letter-spacing:-.035em}

.dn-header{position:absolute;z-index:20;top:0;left:0;width:100%;padding-top:4px}.dn-header-inner{display:grid;grid-template-columns:325px 1fr;background:#fff;box-shadow:0 12px 38px rgba(21,30,51,.08)}.dn-logo{display:flex;align-items:center;justify-content:center;gap:14px;min-height:176px;background:#fff}.dn-logo img{max-width:230px;max-height:115px}.dn-logo i{font-size:70px;color:var(--dn-champagne)}.dn-logo span{font-size:42px;font-weight:700;line-height:.88;color:var(--dn-navy);letter-spacing:.02em}.dn-logo small{display:block;margin-top:12px;font-size:14px;letter-spacing:.02em}.dn-head-main{min-width:0}.dn-topbar{height:68px;display:flex;align-items:center;gap:22px;padding:0 28px;background:var(--dn-navy);color:#fff;font-size:14px;font-weight:600}.dn-topbar>a{margin-left:auto}.dn-topbar i{margin-right:7px}.dn-socials{display:flex;gap:15px}.dn-auth-actions{display:flex;align-items:center;gap:7px;white-space:nowrap}.dn-auth-actions a,.dn-auth-actions button{border:0;background:transparent;padding:4px 0;color:#fff;font:inherit;font-weight:700;cursor:pointer}.dn-auth-actions a:hover,.dn-auth-actions button:hover{color:var(--dn-champagne)}.dn-auth-mobile{display:none}.dn-navbar{height:108px;display:flex;align-items:stretch;background:var(--dn-champagne)}.dn-navbar nav{display:flex;align-items:stretch;flex:1}.dn-navbar nav a{display:flex;align-items:center;padding:0 26px;font-size:17px;font-weight:600;transition:.2s}.dn-navbar nav a:hover{background:rgba(255,255,255,.32)}.dn-consult{display:flex;align-items:center;padding:0 35px;background:rgba(70,84,116,.08);font-family:var(--dn-display);font-size:18px;font-weight:600;text-transform:uppercase}.dn-menu-toggle{display:none}

.dn-hero{min-height:1000px;padding-top:270px;background:var(--dn-navy);color:#fff}.dn-hero::before,.dn-hero::after{content:'';position:absolute;pointer-events:none}.dn-hero::before{width:320px;height:190px;right:5%;top:245px;background:repeating-linear-gradient(135deg,transparent 0 24px,rgba(255,255,255,.68) 25px 28px,transparent 29px 52px)}.dn-hero::after{width:360px;height:105px;right:9%;bottom:48px;background:repeating-linear-gradient(135deg,var(--dn-champagne) 0 28px,var(--dn-navy) 29px 33px,var(--dn-champagne) 34px 62px)}.dn-hero-stage{position:relative;display:grid;grid-template-columns:47% 53%;align-items:center;min-height:650px}.dn-hero-copy{position:relative;z-index:3;padding-right:65px}.dn-hero-copy .dn-eyebrow{font-size:16px}.dn-hero h1{margin:0 0 36px;font-size:40;color:#fff}.dn-hero-copy>p:not(.dn-eyebrow){max-width:760px;margin:0 0 46px;padding-top:34px;border-top:1px solid rgba(255,255,255,.3);font-size:18px;color:#edf0f6}.dn-hero-media{position:relative;z-index:2;height:650px}.dn-hero-media::before{content:'';position:absolute;z-index:-1;inset:-26px 14% auto 14%;height:70px;background:var(--dn-champagne)}.dn-hero-media::after{content:'';position:absolute;left:-30px;bottom:-35px;width:165px;height:335px;border-left:8px solid #fff;border-bottom:8px solid #fff}.dn-hero-slide{position:absolute;inset:0;opacity:0;transform:scale(1.04);transition:opacity .7s ease,transform 1.2s ease}.dn-hero-slide.is-active{opacity:1;transform:scale(1)}.dn-hero-slide img{width:100%;height:100%;object-fit:cover}.dn-hero-dots{position:absolute;z-index:4;bottom:-82px;left:50%;display:flex;gap:12px;transform:translateX(-50%)}.dn-hero-dots button{width:13px;height:13px;padding:0;border:0;background:#65708c}.dn-hero-dots button.is-active{background:var(--dn-champagne)}

.dn-about-grid{display:grid;grid-template-columns:52% 48%;align-items:center}.dn-about-media{position:relative;padding:65px 0 0 70px}.dn-about-media::before{content:'';position:absolute;z-index:-1;top:0;left:0;width:52%;height:52%;background:var(--dn-champagne)}.dn-about-media::after{content:'';position:absolute;left:30px;bottom:-45px;width:58%;height:45%;border-left:3px solid var(--dn-navy);border-bottom:3px solid var(--dn-navy)}.dn-about-media img{width:100%;height:680px;object-fit:cover}.dn-about-copy{padding-left:85px}.dn-about-copy .dn-title{max-width:770px}.dn-about-copy>p:not(.dn-eyebrow){font-size:17px;color:var(--dn-muted);margin:35px 0}.dn-values{display:grid;grid-template-columns:1fr 1fr;gap:26px}.dn-value{display:flex;align-items:center;gap:18px;min-height:80px;padding:18px 24px;background:#f8f8f8;color:var(--dn-navy);text-decoration:none;text-transform:uppercase;font-weight:600;transition:transform .2s ease,background .2s ease,box-shadow .2s ease}.dn-value[href]:hover{transform:translateY(-3px);background:#fff;box-shadow:var(--dn-shadow)}.dn-value i{display:grid;place-items:center;width:52px;height:52px;border-radius:50%;background:var(--dn-champagne);color:var(--dn-navy)}

.dn-services{background:var(--dn-navy);color:#fff}.dn-services-head{display:grid;grid-template-columns:42% 58%;gap:60px;align-items:start}.dn-services .dn-title{color:#fff}.dn-services-head>p{margin:8px 0 0;font-size:18px;line-height:2;color:#e2e7f0}.dn-service-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:40px;margin-top:58px}.dn-card{background:#fff;color:var(--dn-ink);box-shadow:var(--dn-shadow)}.dn-service-image{height:420px;overflow:hidden}.dn-service-image img{width:100%;height:100%;object-fit:cover;transition:transform .6s ease}.dn-card:hover .dn-service-image img{transform:scale(1.055)}.dn-service-body{position:relative;min-height:280px;padding:56px 40px 45px;text-align:center}.dn-service-body h3{position:absolute;top:-38px;left:8%;width:84%;margin:0;padding:22px 16px;background:#fff;font-size:23px;text-transform:uppercase}.dn-service-body p{color:var(--dn-muted);font-size:16px}.dn-round-link{position:absolute;left:50%;bottom:-31px;display:grid;place-items:center;width:62px;height:62px;border-radius:50%;background:var(--dn-champagne);transform:translateX(-50%);transition:.25s}.dn-round-link:hover{transform:translateX(-50%) rotate(-35deg);background:#fff}

.dn-glass-grid{display:grid;grid-template-columns:48% 52%;align-items:start}.dn-glass-image{height:830px;object-fit:cover}.dn-glass-copy{padding:22px 0 0 95px}.dn-glass-copy>p:last-of-type{margin:35px 0 55px;color:var(--dn-muted);font-size:18px}.dn-feature-table{display:grid;grid-template-columns:repeat(3,1fr);margin-left:-210px;background:#fff;box-shadow:var(--dn-shadow)}.dn-feature{display:grid;place-items:center;min-height:195px;padding:28px;border-right:1px solid #ddd;border-bottom:1px solid #ddd;text-align:center;font-family:var(--dn-display);font-size:22px}.dn-feature:nth-child(3n){border-right:0}.dn-feature:nth-last-child(-n+3){border-bottom:0}.dn-feature i{font-size:46px;color:var(--dn-navy)}

.dn-projects .dn-heading{text-align:center}.dn-project-tabs{display:flex;justify-content:center;gap:18px;margin:0 0 42px}.dn-project-tabs button{padding:18px 42px;border:0;background:transparent;color:var(--dn-navy);font-family:var(--dn-display);font-size:18px;font-weight:600;cursor:pointer}.dn-project-tabs button.is-active{background:var(--dn-champagne)}.dn-project-grid{display:grid;grid-template-columns:1.2fr 1.2fr 1fr;grid-template-rows:290px 290px;gap:24px}.dn-project{position:relative;overflow:hidden}.dn-project:first-child{grid-row:1/2}.dn-project:nth-child(2){grid-row:1/3}.dn-project:nth-child(3){grid-row:1/3}.dn-project:nth-child(4){grid-column:1;grid-row:2}.dn-project img{width:100%;height:100%;object-fit:cover;transition:transform .65s}.dn-project::after{content:attr(data-title);position:absolute;inset:auto 0 0;padding:50px 24px 22px;background:linear-gradient(transparent,rgba(29,37,57,.82));color:#fff;font-family:var(--dn-display);font-size:21px;opacity:0;transition:.3s}.dn-project:hover img{transform:scale(1.06)}.dn-project:hover::after{opacity:1}

.dn-styles-grid{display:grid;grid-template-columns:1fr 1.65fr;gap:60px;align-items:center}.dn-style-cards{display:grid;grid-template-columns:1fr 1fr;gap:28px}.dn-style-card{display:grid;place-items:center;min-height:270px;padding:25px;background:#fff;box-shadow:var(--dn-shadow);text-align:center;transition:.28s}.dn-style-card:hover{transform:translateY(-9px);background:var(--dn-cream)}.dn-style-card i{font-size:65px;color:var(--dn-navy)}.dn-style-card h3{margin:24px 0 0;font-size:22px;text-transform:uppercase}.dn-styles-image{position:relative}.dn-styles-image img{width:100%;height:620px;object-fit:cover}.dn-styles-image .dn-btn{position:absolute;right:0;bottom:0}

.dn-newsletter-wrap{padding:75px 0;background:linear-gradient(#fff 50%,var(--dn-navy) 50%)}.dn-newsletter{display:grid;grid-template-columns:1fr 1.1fr;align-items:center;gap:70px;padding:60px 68px;background:var(--dn-champagne)}.dn-newsletter .dn-title{font-size:42px}.dn-newsletter form{display:flex;height:92px;background:#fff}.dn-newsletter input{flex:1;min-width:0;border:0;padding:0 28px;outline:0}.dn-newsletter button{min-width:230px;border:14px solid #fff;background:var(--dn-champagne);font-family:var(--dn-display);font-size:19px;font-weight:700;text-transform:uppercase;cursor:pointer}

.dn-testimonials{background:var(--dn-navy);color:#fff}.dn-testimonial-head{display:grid;grid-template-columns:40% 60%;align-items:start;gap:70px}.dn-testimonials .dn-title{color:#fff}.dn-testimonial-head>p{font-size:17px;color:#e0e5ef}.dn-testimonial-layout{display:grid;grid-template-columns:390px 1fr;gap:80px;margin-top:55px}.dn-stats{display:grid;gap:18px}.dn-stat{display:grid;grid-template-columns:125px 1fr;align-items:center;gap:25px}.dn-stat i{display:grid;place-items:center;height:125px;background:#596684;color:var(--dn-champagne);font-size:38px}.dn-stat strong{display:block;font-size:45px}.dn-stat span{font-weight:600}.dn-quotes{display:grid;grid-template-columns:1fr 1fr;gap:36px}.dn-quote{min-height:330px;padding:50px;background:#fff;color:var(--dn-ink);border-radius:4px}.dn-quote-top{display:flex;align-items:center;gap:22px;margin-bottom:40px}.dn-quote img{width:90px;height:90px;border-radius:50%;object-fit:cover}.dn-quote h3{margin:0;font-size:20px}.dn-quote p{font-size:17px;color:var(--dn-muted)}

.dn-news-head{display:flex;align-items:flex-end;justify-content:space-between}.dn-news-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:52px}.dn-news-card{position:relative;background:#fff;box-shadow:var(--dn-shadow)}.dn-news-card>a>img{width:100%;height:380px;object-fit:cover}.dn-news-body{min-height:270px;padding:65px 42px 35px;text-align:center}.dn-news-date{position:absolute;top:350px;left:50%;padding:14px 28px;background:var(--dn-champagne);transform:translateX(-50%)}.dn-news-body h3{font-size:23px}.dn-news-body a{display:inline-flex;gap:10px;align-items:center;margin-top:18px;font-family:var(--dn-display);font-weight:600;text-transform:uppercase}

.dn-contact .dn-heading{text-align:center}.dn-contact-grid{display:grid;grid-template-columns:42% 58%;align-items:stretch}.dn-contact-info{position:relative;min-height:720px}.dn-contact-info>img{width:100%;height:100%;object-fit:cover}.dn-contact-panel{position:absolute;left:7%;right:7%;bottom:30px;padding:32px 38px;background:rgba(255,255,255,.92)}.dn-contact-panel p{display:flex;gap:22px;align-items:center;font-weight:600}.dn-contact-panel i{font-size:30px}.dn-contact-form{padding:70px;background:var(--dn-champagne)}.dn-contact-form form{display:grid;grid-template-columns:1fr 1fr;gap:24px}.dn-contact-form input,.dn-contact-form textarea{width:100%;border:0;background:#fff;padding:22px 24px;outline:0}.dn-contact-form textarea{grid-column:1/-1;min-height:190px;resize:vertical}.dn-contact-form .dn-btn{grid-column:1/-1;background:var(--dn-navy);color:#fff}

.dn-contact-page{background:#f7f8fa}.dn-contact-page-hero{position:relative;overflow:hidden;padding:285px 0 105px;background:linear-gradient(135deg,var(--dn-navy-deep),var(--dn-navy));color:#fff}.dn-contact-page-hero::before{content:"";position:absolute;width:520px;height:520px;right:-150px;bottom:-330px;border:1px solid rgba(231,204,152,.2);border-radius:50%;box-shadow:0 0 0 75px rgba(231,204,152,.025),0 0 0 150px rgba(231,204,152,.018)}.dn-contact-page-hero__inner{position:relative;display:flex;align-items:center;justify-content:space-between;gap:60px}.dn-contact-page-hero__inner>div:first-child{max-width:920px}.dn-contact-page-hero h1{max-width:950px;margin:0;color:#fff;font-size:clamp(48px,5vw,82px);letter-spacing:-.035em}.dn-contact-page-hero__inner>div:first-child>p:last-child{max-width:780px;margin:24px 0 0;color:rgba(255,255,255,.75);font-size:18px}.dn-contact-page-hero__mark{display:grid;place-items:center;width:148px;height:148px;flex:0 0 auto;border:1px solid rgba(231,204,152,.4);background:rgba(255,255,255,.05);color:var(--dn-champagne);font-size:54px;transform:rotate(4deg)}.dn-contact-page-body{padding-top:95px}.dn-contact-page-grid{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:55px;align-items:start}.dn-contact-details{position:relative;overflow:hidden;padding:52px;background:var(--dn-navy);color:#fff;box-shadow:0 30px 80px rgba(31,42,67,.16)}.dn-contact-details::after{content:"";position:absolute;width:240px;height:240px;right:-150px;top:-140px;border:35px solid rgba(231,204,152,.08);border-radius:50%}.dn-contact-details h2{position:relative;max-width:620px;margin:0;font-size:clamp(35px,3vw,52px);color:#fff}.dn-contact-details__lead{margin:24px 0 34px;color:rgba(255,255,255,.72);font-size:16px}.dn-contact-detail-list{display:grid;gap:12px}.dn-contact-detail{display:grid;grid-template-columns:52px minmax(0,1fr) auto;align-items:center;gap:15px;min-height:90px;padding:17px 19px;border:1px solid rgba(255,255,255,.11);background:rgba(255,255,255,.055);transition:.25s}.dn-contact-detail:hover{border-color:rgba(231,204,152,.7);background:rgba(231,204,152,.1);transform:translateX(5px)}.dn-contact-detail>i{display:grid;place-items:center;width:48px;height:48px;background:rgba(231,204,152,.14);color:var(--dn-champagne);font-size:19px}.dn-contact-detail span>*{display:block}.dn-contact-detail small{margin-bottom:4px;color:rgba(255,255,255,.55);font-size:11px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.dn-contact-detail strong{overflow-wrap:anywhere;font-size:14px}.dn-contact-detail>b{color:var(--dn-champagne);font-size:12px}.dn-contact-page-note{margin-top:28px;padding-top:24px;border-top:1px solid rgba(255,255,255,.12);color:rgba(255,255,255,.72);font-size:14px}.dn-contact-page-note h1,.dn-contact-page-note h2,.dn-contact-page-note h3{color:#fff;font-size:20px}.dn-contact-request{padding:52px;background:#fff;box-shadow:0 30px 80px rgba(31,42,67,.09)}.dn-contact-request>header>span{color:#b38c49;font-size:12px;font-weight:800;letter-spacing:.14em;text-transform:uppercase}.dn-contact-request h2{margin:9px 0 12px;color:var(--dn-navy);font-size:clamp(34px,3vw,48px)}.dn-contact-request>header>p{margin:0;color:var(--dn-muted)}.dn-contact-page-form{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:32px}.dn-contact-page-form label{display:grid;gap:7px;color:var(--dn-navy);font-size:12px;font-weight:800}.dn-contact-page-form label.is-wide,.dn-contact-page-form .dn-contact-privacy,.dn-contact-page-form .dn-btn{grid-column:1/-1}.dn-contact-page-form input,.dn-contact-page-form select,.dn-contact-page-form textarea{width:100%;min-height:54px;padding:0 16px;border:1px solid #dde2e9;background:#fbfcfd;color:var(--dn-ink);outline:0}.dn-contact-page-form textarea{min-height:150px;padding-top:15px;resize:vertical}.dn-contact-page-form input:focus,.dn-contact-page-form select:focus,.dn-contact-page-form textarea:focus{border-color:var(--dn-navy);background:#fff;box-shadow:0 0 0 4px rgba(70,84,116,.09)}.dn-contact-page-form label small{color:#b32d2d;font-weight:600}.dn-contact-page-form .dn-btn{width:100%;background:var(--dn-navy);color:#fff}.dn-contact-privacy{display:flex;align-items:center;gap:9px;margin:0;color:var(--dn-muted);font-size:12px}.dn-contact-privacy i{color:#4c8b63}.dn-contact-alert{display:flex;align-items:center;gap:10px;margin-top:22px;padding:14px 16px;font-size:14px;font-weight:700}.dn-contact-alert.is-success{background:#edf8f0;color:#287341}.dn-contact-alert.is-error{background:#fff1f1;color:#aa2f2f}

